 attack(){const p=this.player;if(p.fire>0||p.reload>0||p.heal>0||p.melee>0||this.mode!=='playing')return;if(!p.weapon){this.meleeAttack();return;}const spec=this.weaponSpec();if(p.mag===0){this.command('reload');return;}p.mag--;p.fire=spec.interval;this.shots++;this.noise(p,spec.noise);const spread=(p.crouch?.012:p.moving?.07:.025)+(p.stamina<15?.035:0),angle=p.angle+(this.random()-.5)*spread*spec.spread,dir={x:Math.sin(angle),z:Math.cos(angle)},max=spec.range;let hitDist=max,hit=null;const end={x:p.x+dir.x*max,z:p.z+dir.z*max};for(const b of this.nav.boxes){const t=segmentBox(p,end,b);if(t!==null&&t*max<hitDist){hitDist=t*max;hit=null;}}for(const g of this.guards){if(g.state==='down')continue;const vx=g.x-p.x,vz=g.z-p.z,t=vx*dir.x+vz*dir.z,perp=Math.abs(vx*dir.z-vz*dir.x);if(t>0&&t<hitDist&&perp<.65){hitDist=t;hit=g;}}if(hit){this.harm(hit,spec.damage,true);this.hits++;}this.emit('shot',{from:{x:p.x,z:p.z},to:{x:p.x+dir.x*hitDist,z:p.z+dir.z*hitDist},hit:!!hit,enemy:false,angle,weapon:p.weaponId,shooterId:'player'});}
